// apps/worker/src/test-support/fixtures.ts
//
// Database fixtures for the worker's job tests.
//
// apps/web/src/test exports only a reset helper, and this stage may not modify
// apps/web, so the builders live here. They create the smallest valid FK chain
// for a slot and delete it again in reverse order:
//
//   User -> Creator -> CampaignCreatorSlot <- Campaign -> Organization
//                  \- SocialAccount (only when a test asks for one)
//
// Every id is generated by Prisma and every row is tagged with a random suffix,
// so two fixtures can never collide and cleanup is by id, never by pattern.

import { randomBytes } from 'node:crypto';

import { prisma, SlotStatus } from '@repo/database';

export interface CampaignFixture {
  /** Zero, one or many slots; every slot in the fixture belongs to this campaign. */
  slotIds: string[];
  campaignId: string;
  organizationId: string;
  creatorIds: string[];
  userIds: string[];
  /** SocialAccount rows created for this fixture, one per slot at most. */
  socialAccountIds: string[];
}

export interface CreateInvitesOptions {
  /** How many slots to create, each with its own creator. Defaults to 1. */
  count?: number;
  /** Defaults to one minute in the past: an expired invite. `null` means never. */
  inviteExpiresAt?: Date | null;
  status?: SlotStatus;
  deletedAt?: Date | null;
  escrowAmount?: string;
  /**
   * Creates one YouTube SocialAccount per creator and points the slot at it, so
   * `socialAccountId` is populated. Off by default: it is one more row to clean
   * up, and only a test that compares whole rows needs it.
   */
  withSocialAccount?: boolean;
}

/** A unique, lowercase suffix for generated identifiers. */
function tag(): string {
  return randomBytes(6).toString('hex');
}

/**
 * Creates one organization, one campaign and `count` creators, each holding one
 * slot in the requested state.
 *
 * If anything fails part-way, the rows created so far are deleted before the
 * error is rethrown: a fixture that never returned cannot be cleaned up by the
 * caller, and a half-built fixture would otherwise outlive its test and quietly
 * change the counts other tests assert on.
 */
export async function createCampaignWithInvites(
  options: CreateInvitesOptions = {},
): Promise<CampaignFixture> {
  const suffix = tag();
  const count = options.count ?? 1;

  const fixture: CampaignFixture = {
    slotIds: [],
    campaignId: '',
    organizationId: '',
    creatorIds: [],
    userIds: [],
    socialAccountIds: [],
  };

  try {
    const organization = await prisma.organization.create({
      data: { name: `worker fixture org ${suffix}` },
    });
    fixture.organizationId = organization.id;

    const campaign = await prisma.campaign.create({
      data: {
        organizationId: organization.id,
        title: `worker fixture campaign ${suffix}`,
        totalBudget: '10000.00',
      },
    });
    fixture.campaignId = campaign.id;

    const inviteExpiresAt =
      options.inviteExpiresAt === undefined
        ? new Date(Date.now() - 60_000)
        : options.inviteExpiresAt;

    for (let index = 0; index < count; index += 1) {
      const user = await prisma.user.create({
        data: {
          clerkId: `worker_fixture_clerk_${suffix}_${index}`,
          email: `worker_fixture_${suffix}_${index}@example.test`,
        },
      });
      fixture.userIds.push(user.id);

      const creator = await prisma.creator.create({ data: { userId: user.id } });
      fixture.creatorIds.push(creator.id);

      let socialAccountId: string | undefined;
      if (options.withSocialAccount) {
        // Only the required columns: the token envelope is optional and this row
        // exists to be pointed at, not to be used for a call.
        const socialAccount = await prisma.socialAccount.create({
          data: {
            creatorId: creator.id,
            platform: 'YOUTUBE',
            externalId: `worker_fixture_channel_${suffix}_${index}`,
            scopes: [],
          },
        });
        fixture.socialAccountIds.push(socialAccount.id);
        socialAccountId = socialAccount.id;
      }

      const slot = await prisma.campaignCreatorSlot.create({
        data: {
          campaignId: campaign.id,
          creatorId: creator.id,
          status: options.status ?? SlotStatus.INVITED,
          escrowAmount: options.escrowAmount ?? '500.00',
          inviteExpiresAt,
          ...(options.deletedAt !== undefined ? { deletedAt: options.deletedAt } : {}),
          ...(socialAccountId !== undefined ? { socialAccountId } : {}),
        },
      });
      fixture.slotIds.push(slot.id);
    }

    return fixture;
  } catch (error) {
    // Best effort, and never mask the original error with a cleanup error.
    await removeFixture(fixture).catch(() => undefined);
    throw error;
  }
}

/**
 * Deletes a fixture in FK order. Restricted relations (slot -> creator,
 * slot -> socialAccount, campaign -> organization) mean the order matters;
 * nothing here relies on cascade.
 *
 * Safe to call on a partially built fixture: empty id lists delete nothing.
 */
export async function removeFixture(fixture: CampaignFixture): Promise<void> {
  // PayoutEvent rows are never created by these fixtures, but a slot cannot be
  // deleted while one exists, so a stray row from an aborted test would surface
  // here as a clear failure instead of a mystery in the next test.
  await prisma.campaignCreatorSlot.deleteMany({ where: { id: { in: fixture.slotIds } } });
  // After the slots and before the creators: both FKs are Restrict.
  await prisma.socialAccount.deleteMany({ where: { id: { in: fixture.socialAccountIds } } });
  await prisma.creator.deleteMany({ where: { id: { in: fixture.creatorIds } } });
  await prisma.campaign.deleteMany({ where: { id: fixture.campaignId } });
  await prisma.organization.deleteMany({ where: { id: fixture.organizationId } });
  await prisma.user.deleteMany({ where: { id: { in: fixture.userIds } } });
}
